Definition bp_setup_stmt (pc callee ret : Z) : Prop :=
  forall (rax : word) (spa : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff p1 n : Z)
         (t3 t4 t5 t6 : word) (F : bvmap 5 word) fc (m : mem),
  0 <= spa -> spa + 184 < 2^64 ->
  evt bsegs (fun ms' => ms' = bp_ms callee (wz ret) spa gp tp t0 t1 t2 sp0 (wz P) (wz (spa + 176)) (wz n) (wz E) a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m)
    (bp_ms pc rax spa gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 E P ff p1 n t3 t4 t5 t6 F fc m).

