Lemma bp_arm9a : forall (rax : word) (spa lo shi : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff n : Z)
    (t3 t4 t5 t6 : word) (F : bvmap 5 word) fc (m : mem) (c : pcore) (pad7 pad2 j0 j128 j152 : list byte) (p0 p1 p : Z) (E1 : ecv),
  rw_cells bsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  rw_cells bsegs m spa (bp_locals E P p0 ff j0 j128 j152 p) ->
  rw_cells bsegs m E (ErrCodeCells E1) ->
  AXStatics2 m ->
  stk bsegs m lo spa -> aceil <= lo -> lo + 64 + AINTRIN_STACK <= spa -> spa + 184 <= shi ->
  accessible m P 344 -> P mod 8 = 0 -> aapp P 344 -> aapp E 24 -> E mod 8 = 0 -> (P + 344 <= E \/ E + 24 <= P) ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> accessible m E 24 -> shvis m E (E + 24) ->
  0 <= p < 2^64 -> 0 <= n < 2^64 ->
  evt bsegs (fun ms' => exists t0' t1' t2' a6' a7' t3' t4' t5' t6' m',
       ms' = MS (mkR (wz BP_PCB_RET) (wz (spa + -64)) gp tp t0' t1' t2' (wz P) (wz (spa + 176)) (wz P) (wz (pc_len c)) (wz p) (wz (Z.min (pc_len c) n)) (wz E)
                     (wz P_A_ON_CHUNK_BODY_IMPL) a6' a7'
                     (wz (P + 24)) (wz E) (shw (spa + 176)) (wz 2147450880) (shw (P + 24)) (wz (E + 16)) (wz BP_JT) (wz n) (shw ff) (shw (P + 72)) t3' t4' t5' t6')
                F (wz P_A_ON_CHUNK_BODY_IMPL) fc None m' (seg_rom bsegs)
       /\ munch [(lo, spa); (E, E + 24)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
       /\ stk bsegs m' lo (spa + -64)
       /\ rw_cells bsegs m' (spa + -64) (bp_pcbfr spa sp0 E P p1)
       /\ rw_cells bsegs m' E (ErrCodeCells EC_clear)
       /\ ACONST m' /\ stack0 m' lo shi)
